// The one cue source (Plan 07 A2). There is NO second audio timeline.
//
//   AUTHORED: motion/score.json  ->  `audio_cues: [{id, event, role, source, intent, offset_s, ...}]` next to the existing `events[].sound`, `seams[].sound`,
//             `hits` and `music_arc` (all still read: see legacyCues). A cue names a STABLE visual/narrative event id; it stores no film time of its own.
//   DERIVED:  film time comes from lib/timing.mjs eventsFromScore (the same events motion/events.json holds). motion/cues.json is derived from the
//             score (score_revision stamped, regenerated by writeCues, never edited), so retiming a scene moves its cues with it.
//
// Timing fields are kept apart on purpose (a clip's loudest sample is not automatically its sync point):
//   picture_onset_s   the visual event (from the score)            speech_word_s   a spoken word's onset, when the cue is tied to speech
//   intended_offset_s where the sound's ACCENT should sit relative to the picture (negative = anticipates, positive = trails)
//   sfx_onset_s       where the FILE starts in film time (= picture + intended offset - the file's accent point)
//   acoustic_peak_s   where the measured accent actually lands (sfx_onset_s + the file's measured sync point); null until measured
//   An intentional lead or lag is RECORDED (intent: anticipate | trail), not rejected. Only a cue marked synchronous, a spoken-word highlight, or lip
//   movement is held to a hard tolerance; everything else is compared with ITS OWN target, never with zero.
//
//   normalizeCue(raw), legacyCues(score), authoredCues(score), cuesFromScore(score), resolveCue(cue, events, o), checkCue(cue, o)
//   silenceViolations(cues, windows), dropInSilence(items, windows), transitionStacking(cues, seams, o), seamIntent(seam)
//   deriveCues(score, o), writeCues(run), cuesFresh(run), toSfxEvents(cues)
//   Addendum 2 (additive; a cue without these fields normalizes byte-identically): optional `layers`, `purpose`, `family`, `intensity`,
//   `perceptual_event_id`, `music_reduction` on a cue (layer shape: normalizeLayer); overlapReport(resolvedCues, o) balances overlapping events as a whole.
//   Planning of the layers lives in lib/sfx-layers.mjs (planCueLayers, effectsPolicy, eventDensity, resourceLayers, coherentFamily).
import fs from "node:fs";
import path from "node:path";
import { canonicalDigest, SCHEMA_VERSION } from "./contracts.mjs";
import { eventsFromScore, scoreRevision, scoreRate } from "./timing.mjs";
import { readDirection, silenceWindows } from "./audio-direction.mjs";

const isObj = (x) => x !== null && typeof x === "object" && !Array.isArray(x);
const arr = (x) => (Array.isArray(x) ? x : []);
const T = (x) => (typeof x === "string" ? x.trim() : x == null ? "" : String(x).trim());
const num = (x, d = null) => (x !== null && x !== "" && x !== undefined && Number.isFinite(Number(x)) ? Number(x) : d);
const r3 = (x) => (x == null ? x : Math.round(x * 1000) / 1000);
const rjson = (p) => { try { return JSON.parse(fs.readFileSync(p, "utf8")); } catch { return null; } };

export const CUE_ROLES = ["accent", "impact", "transition", "ui", "foley", "ambience", "music_hit", "vo_highlight", "riser", "stinger", "lip_sync"];
export const INTENTS = ["on_picture", "anticipate", "trail", "synchronous"];
// the existing default, kept as a DEFAULT: the accent lands 10 ms after the picture (sound.mjs sfx-plan), which reads as simultaneous
export const DEFAULT_OFFSET_S = 0.01;
const HARD_ROLES = new Set(["vo_highlight", "lip_sync"]);
// Addendum 2: a layer has ONE job. onset.lead says how it relates to the visible action: before it, with it, or after it
export const LAYER_ROLES = ["movement", "accent", "texture", "tail", "ui"];
export const LAYER_LEADS = ["leads", "confirms", "trails"];
export const CUE_INTENSITIES = ["light", "medium", "prominent"];
export const leadOf = (offset_s) => (offset_s < -0.02 ? "leads" : offset_s > 0.06 ? "trails" : "confirms");
// one layer of a cue; onset is relative to the event (basis "event": the event's score-derived time + offset_s, never film time)
export function normalizeLayer(raw) {
  const x = isObj(raw) ? raw : {};
  const on = isObj(x.onset) ? x.onset : {};
  const off = num(on.offset_s ?? x.offset_s, 0);
  const lead = LAYER_LEADS.includes(T(on.lead)) ? T(on.lead) : leadOf(off);
  return {
    role: LAYER_ROLES.includes(T(x.role)) ? T(x.role) : "accent",
    asset_ref: T(x.asset_ref || x.asset) || null,
    gain_db: num(x.gain_db ?? (isObj(x.gain) ? x.gain.db : null), 0),
    pan: num(x.pan),
    tonal: isObj(x.tonal) ? x.tonal : null,
    onset: { basis: "event", offset_s: off, lead },
    body_s: num(x.body_s), tail_s: num(x.tail_s),
    ...(T(x.job) ? { job: T(x.job) } : {}),
    ...(T(x.why) ? { why: T(x.why) } : {}),
  };
}

// ---- the cue record -------------------------------------------------------------------------------------------------------------------------
export function normalizeCue(raw, { legacy = false } = {}) {
  const x = isObj(raw) ? raw : {};
  const role = CUE_ROLES.includes(T(x.role)) ? T(x.role) : "accent";
  const synchronous = x.synchronous === true || x.intent === "synchronous" || HARD_ROLES.has(role);
  let intent = INTENTS.includes(T(x.intent)) ? T(x.intent) : synchronous ? "synchronous" : null;
  let off = num(x.intended_offset_s ?? x.offset_s);
  if (!intent) intent = off == null || Math.abs(off - DEFAULT_OFFSET_S) < 1e-9 ? "on_picture" : off < 0 ? "anticipate" : "trail";
  if (off == null) off = intent === "synchronous" ? 0 : DEFAULT_OFFSET_S;
  const src = isObj(x.source) ? x.source : {};
  const g = isObj(x.gain) ? x.gain : {};
  const sp = isObj(x.spatial) ? x.spatial : {};
  const conf = isObj(x.confidence) ? x.confidence : { value: num(x.confidence), basis: "" };
  return {
    id: T(x.id) || (T(x.event) ? `cue-${T(x.event)}` : ""),
    event_id: T(x.event_id || x.event),
    source: { asset: T(src.asset || x.asset) || null, kind: T(src.kind) || null, file: T(src.file || x.file) || null, sample: T(src.sample || x.sample) || null, rights_ref: T(src.rights_ref) || null },
    role, intent, synchronous, tolerance_s: num(x.tolerance_s),
    intended_offset_s: off,
    speech_word: T(x.word) || null, speech_word_s: num(x.speech_word_s),
    acoustic_peak_in_file_s: num(x.measured && x.measured.peak_s != null ? x.measured.peak_s : x.sync_point), // the file's own accent point: measured, never assumed
    duration_s: num(x.duration_s),
    placed_onset_s: num(x.placed_onset_s), // where the file ACTUALLY starts once mounted or measured in a render (film time); absent until something places it. The check compares this with the plan
    gain: { db: num(g.db ?? x.gain_db, 0), envelope: arr(g.envelope ?? x.envelope).filter((p) => Array.isArray(p) && p.length === 2).map(([t, d]) => [Number(t), Number(d)]) },
    spatial: { pan: num(sp.pan ?? x.pan), intent: T(sp.intent) || (num(sp.pan ?? x.pan) != null ? "positional" : "centered") },
    confidence: { value: conf.value == null ? null : Math.max(0, Math.min(1, Number(conf.value))), basis: T(conf.basis) },
    breaks_silence: x.breaks_silence === true ? { reason: T(x.break_reason) || "" } : null,
    // Addendum 2, optional: present only when the raw cue carries them (legacy cue shape unchanged)
    ...(Array.isArray(x.layers) && x.layers.length ? { layers: x.layers.map(normalizeLayer) } : {}),
    ...(T(x.purpose) ? { purpose: T(x.purpose) } : {}),
    ...(T(x.family) ? { family: T(x.family) } : {}),
    ...(CUE_INTENSITIES.includes(T(x.intensity)) ? { intensity: T(x.intensity) } : {}),
    ...(T(x.perceptual_event_id) ? { perceptual_event_id: T(x.perceptual_event_id) } : {}),
    ...(isObj(x.music_reduction) ? { music_reduction: { depth_db: num(x.music_reduction.depth_db), reason: T(x.music_reduction.reason) } } : {}),
    ...(legacy ? { legacy: true } : {}),
  };
}

// score.audio_cues[] (the authored extension)
export const authoredCues = (score) => arr(score && score.audio_cues).map((c) => normalizeCue(c));

// the cues old scores already imply: an event's `sound`/`sfx`/`kind` and a seam's `sound`/`sfx`. Read as-is (legacy: true); a seam without a sound,
// or marked editorial.silent, makes NO cue and is not an error.
export function legacyCues(score) {
  const out = [];
  arr(score && score.scenes).forEach((sc, i) => arr(sc.events).forEach((ev, j) => {
    const snd = T(ev.sound || ev.sfx);
    if (!snd) return;
    out.push(normalizeCue({ id: `cue-${T(ev.id) || `s${i + 1}-e${j + 1}`}`, event: T(ev.id) || `s${i + 1}-e${j + 1}`, source: { sample: snd }, role: /whoosh|riser|impact|hit|stinger/.test(snd) ? (/riser/.test(snd) ? "riser" : /impact|hit/.test(snd) ? "impact" : "transition") : "accent", word: ev.word }, { legacy: true }));
  }));
  arr(score && score.seams).forEach((sm) => {
    const snd = T(sm.sound || sm.sfx);
    if (!snd || (sm.editorial && sm.editorial.silent === true)) return;
    out.push(normalizeCue({ id: `cue-seam-${sm.from}-${sm.to}`, event: `seam-${sm.from}-${sm.to}`, source: { sample: snd }, role: /riser/.test(snd) ? "riser" : /impact|hit/.test(snd) ? "impact" : "transition" }, { legacy: true }));
  });
  return out;
}

// authored cues win over a legacy cue for the same event id (an authored one is a decision about that event)
export function cuesFromScore(score) {
  const a = authoredCues(score), seen = new Set(a.map((c) => c.event_id));
  return [...a, ...legacyCues(score).filter((c) => !seen.has(c.event_id))];
}

// ---- timing: derived, never stored ------------------------------------------------------------------------------------------------------
// events: [{id, t, ...}] from eventsFromScore. o: { fps (for default tolerances) }
export function resolveCue(cue, events, { words = [] } = {}) {
  const ev = arr(events).find((e) => e.id === cue.event_id);
  if (!ev) return { ...cue, resolved: false, problem: `event ${JSON.stringify(cue.event_id)} is not in the score's events (a cue needs a stable event id; a renamed event is a conflict, not a guess)` };
  const picture = ev.t;
  let word = cue.speech_word_s;
  if (word == null && cue.speech_word) { const w = arr(words).find((x) => T(x.text || x.w).toLowerCase() === cue.speech_word.toLowerCase() && Math.abs(num(x.start, 1e9) - picture) < 1.5); if (w) word = num(w.start); }
  const peakIn = cue.acoustic_peak_in_file_s;
  const planned = peakIn != null ? picture + cue.intended_offset_s - peakIn : picture + cue.intended_offset_s; // unmeasured file: its start is assumed to be its accent, and says so
  const sfxOnset = cue.placed_onset_s != null ? cue.placed_onset_s : planned; // an actual placement (sfx-plan mount, or a measured render) is judged against the plan
  const acoustic = peakIn != null ? sfxOnset + peakIn : null;
  return {
    ...cue, resolved: true,
    timing: {
      picture_onset_s: r3(picture),
      speech_word_s: word == null ? null : r3(word),
      intended_offset_s: r3(cue.intended_offset_s),
      planned_onset_s: r3(Math.max(0, planned)),
      sfx_onset_s: r3(Math.max(0, sfxOnset)), // file start in film time (clamped at 0: a cue cannot start before the film)
      acoustic_peak_s: acoustic == null ? null : r3(acoustic),
      measured_offset_s: acoustic == null ? null : r3(acoustic - picture),
      peak_basis: peakIn != null ? "measured sync point of the file" : "not measured: the file start is taken as its accent",
      placement: cue.placed_onset_s != null ? "placed (mounted or measured)" : "planned (not yet placed)",
    },
    confidence: peakIn != null || cue.confidence.value != null ? cue.confidence : { value: 0.5, basis: "the file's sync point has not been measured" },
  };
}

// compare with the cue's OWN target. Errors only for cues that are held to a hard sync (synchronous, spoken-word highlight, lip sync).
export function checkCue(rc, { fps = 30 } = {}) {
  const frame = 1 / fps, issues = [];
  if (!rc.resolved) return [{ severity: "error", check: "cue-event-missing", cue: rc.id, message: rc.problem }];
  const t = rc.timing;
  if (!rc.id) issues.push({ severity: "error", check: "cue-id", cue: rc.id, message: "a cue needs a stable id" });
  if (!rc.source.asset && !rc.source.file && !rc.source.sample) issues.push({ severity: "warning", check: "cue-no-source", cue: rc.id, message: "no source asset: the cue has nothing to play (it is skipped, and the downgrade belongs in the log)" });
  if (t.measured_offset_s != null) {
    const dev = t.measured_offset_s - t.intended_offset_s; // against its own target
    if (rc.synchronous) {
      const tol = rc.tolerance_s ?? frame; // hard sync is for cues that DESIGNATE it
      if (Math.abs(dev) > tol + 1e-9) issues.push({ severity: "error", check: "sync-off-target", cue: rc.id, message: `synchronous cue lands ${r3(dev * 1000)} ms from its target (tolerance ${r3(tol * 1000)} ms)`, deviation_s: r3(dev) });
    } else {
      const tol = rc.tolerance_s ?? 2 * frame;
      if (Math.abs(dev) > tol + 1e-9) issues.push({ severity: "warning", check: "offset-drift", cue: rc.id, message: `lands ${r3(dev * 1000)} ms from its intended offset ${r3(t.intended_offset_s * 1000)} ms (${rc.intent}); an intentional lead or lag is fine, a drift from it is not`, deviation_s: r3(dev) });
    }
  }
  if (rc.role === "vo_highlight" && t.speech_word_s == null) issues.push({ severity: "warning", check: "word-time-missing", cue: rc.id, message: "a spoken-word highlight needs the word's measured onset (speech_word_s): the cue cannot be held to the word without it" });
  if (rc.synchronous && t.acoustic_peak_s == null) issues.push({ severity: "warning", check: "sync-unmeasured", cue: rc.id, message: "synchronous cue whose accent was never measured: sync is unverified, not assumed good" });
  return issues;
}

// ---- silence is protected -----------------------------------------------------------------------------------------------------------------------
const inWin = (w, t0, t1) => t0 < w.end_s && w.start_s < Math.max(t1, t0 + 1e-6);
export function silenceViolations(resolvedCues, windows) {
  const out = [];
  for (const c of arr(resolvedCues)) {
    if (!c.resolved) continue;
    const t0 = c.timing.sfx_onset_s, t1 = t0 + (c.duration_s ?? 0.3);
    for (const w of arr(windows)) {
      if (!inWin(w, t0, t1)) continue;
      if (c.breaks_silence || arr(w.allow).includes(c.id)) continue; // deliberate
      out.push({ cue: c.id, window: w.id, kind: w.kind, message: `cue ${c.id} sounds inside the ${w.kind} silence window ${w.id} (${r3(w.start_s)}-${r3(w.end_s)} s): ${w.why || "protected"}; mark breaks_silence with a reason if it is deliberate` });
    }
  }
  return out;
}
// auto-fill (sfx-plan candidates, riser/impact helpers) never lands in a protected window. items: [{id, t, ...}]
export function dropInSilence(items, windows) {
  const kept = [], dropped = [];
  for (const it of arr(items)) {
    const w = arr(windows).find((x) => num(it.t) != null && it.t >= x.start_s && it.t < x.end_s && !arr(x.allow).includes(it.id) && !it.breaks_silence);
    if (w) dropped.push({ ...it, why: `inside the protected ${w.kind} silence window ${w.id}` }); else kept.push(it);
  }
  return { kept, dropped };
}

// ---- no riser + impact at every change ------------------------------------------------------------------------------------------------------
// A transition formula is a STYLE choice, not a requirement. This reports how much of the film uses it so the Director can decide; it never
// demands one, and only warns when nearly every change carries the same riser-then-impact pair.
export function transitionStacking(resolvedCues, seams = [], { window_s = 1.5, share = 0.6, min_seams = 3 } = {}) {
  const rc = arr(resolvedCues).filter((c) => c.resolved);
  const risers = rc.filter((c) => c.role === "riser"), impacts = rc.filter((c) => c.role === "impact");
  const stacked = [];
  for (const s of arr(seams)) {
    const t = num(s.t);
    if (t == null) continue;
    const near = (list) => list.some((c) => Math.abs(c.timing.picture_onset_s - t) <= window_s);
    if (near(risers) && near(impacts)) stacked.push(s.id || `seam@${t}`);
  }
  const n = arr(seams).length, frac = n ? stacked.length / n : 0;
  const warn = n >= min_seams && frac >= share;
  return { seams: n, stacked, share: r3(frac), warn, message: warn ? `${stacked.length} of ${n} changes carry a riser and an impact: a formula, not a decision. Let some changes cut clean or take one sound (this is a style default, not a rule)` : null };
}

// ---- overlapping events are balanced as a whole ------------------------------------------------------------------------------------------
// Clusters cues whose sounds start within window_s of each other (single-linkage on the sound's onset) and reports each cluster as ONE perceptual
// group: how many perceptual events (a multi-layer cue is one event), how many actual layers, how many prominent ones, and a riser+impact stack. It reports; the
// plan decides. perWindow / max_prominent default to the existing SFX_BUDGET numbers (audio.mjs, read-only: pass o.budget to use the real row).
// Never hides overload: layers are listed next to events, and a cluster is flagged on EITHER count.
export function overlapReport(resolvedCues, { window_s = 1, budget = null, perWindow = null, max_layers = null, max_prominent = 1 } = {}) {
  const cap = perWindow ?? (budget && num(budget.perWindow)) ?? 3;
  const lcap = max_layers ?? cap * 2;
  const items = arr(resolvedCues).filter((c) => c && c.resolved && c.timing).map((c) => ({ c, t: c.timing.sfx_onset_s })).sort((a, b) => a.t - b.t);
  const groups = [];
  for (const it of items) {
    const g = groups[groups.length - 1];
    if (g && it.t - g.last <= window_s) { g.items.push(it); g.last = it.t; } else groups.push({ items: [it], first: it.t, last: it.t });
  }
  const prominent = (c) => c.intensity === "prominent" || ["impact", "stinger", "riser"].includes(c.role);
  const out = groups.map((g) => {
    const cues = g.items.map((x) => x.c);
    const events = new Set(cues.map((c) => c.perceptual_event_id || c.event_id || c.id)).size;
    const layers = cues.reduce((n, c) => n + (c.layers ? c.layers.length : 1), 0);
    const prom = cues.filter(prominent).length;
    const stack = cues.some((c) => c.role === "riser") && cues.some((c) => c.role === "impact");
    const flags = [];
    if (events > cap) flags.push("events_over_window");
    if (layers > lcap) flags.push("layers_over_window");
    if (prom > max_prominent) flags.push("prominent_stacked");
    if (stack) flags.push("riser_impact_stack");
    return { start_s: r3(g.first), end_s: r3(g.last), cues: cues.map((c) => c.id), events, layers, prominent: prom, flags };
  }).filter((g) => g.events > 1 || g.layers > 1 || g.flags.length);
  const flagged = out.filter((g) => g.flags.length);
  return {
    window_s, per_window_cap: cap, layer_cap: lcap, groups: out, flagged: flagged.length,
    message: flagged.length ? `${flagged.length} overlapping group(s) crowd the same moment (${[...new Set(flagged.flatMap((g) => g.flags))].join(", ")}): thin or space them as one event, not one cue at a time` : null,
  };
}

// a seam's declared sound intent: hard cut / hold / editorial.silent seams are owed nothing
export function seamIntent(seam) {
  const e = isObj(seam && seam.editorial) ? seam.editorial : {};
  if (e.silent === true) return { owes_sound: false, why: "editorial.silent" };
  if (e.hard_cut || e.hold) return { owes_sound: false, why: e.hard_cut ? "deliberate hard cut" : "deliberate hold" };
  if (String(seam && seam.kind) === "cut") return { owes_sound: false, why: "a cut" };
  return { owes_sound: null, why: "a moving seam: a sound is available, not owed" };
}

// ---- derive and write ----------------------------------------------------------------------------------------------------------------------------
export function deriveCues(score, { words = [], silence = [] } = {}) {
  const ev = eventsFromScore(score);
  const fps = scoreRate(score).fps;
  const cues = cuesFromScore(score).map((c) => resolveCue(c, ev.events, { words }));
  const issues = cues.flatMap((c) => checkCue(c, { fps }));
  for (const v of silenceViolations(cues, silence)) issues.push({ severity: "warning", check: "cue-in-silence", cue: v.cue, message: v.message });
  const seams = ev.events.filter((e) => /^seam-/.test(e.id)).map((e) => ({ id: e.id, t: e.t }));
  const stack = transitionStacking(cues, seams);
  if (stack.warn) issues.push({ severity: "warning", check: "riser-impact-formula", message: stack.message });
  return {
    schema_version: SCHEMA_VERSION, derived: true,
    note: "derived from motion/score.json (audio_cues, events and seams); edit the score, not this file",
    score_revision: scoreRevision(score), frame_rate: ev.frame_rate, convention: ev.convention,
    cues: cues.map(({ resolved, problem, ...c }) => ({ ...c, resolved, ...(problem ? { problem } : {}) })),
    issues, digest: canonicalDigest(cues.map((c) => [c.id, c.event_id, c.timing && c.timing.sfx_onset_s, c.source, c.gain, c.spatial, ...(c.layers ? [c.layers, c.purpose || null, c.family || null, c.intensity || null] : [])])),
  };
}
export function writeCues(run) {
  const score = rjson(path.join(String(run), "motion", "score.json"));
  if (!score) return { ok: false, error: "motion/score.json is missing or invalid" };
  const dir = readDirection(run);
  const ev = eventsFromScore(score).events;
  const win = dir.direction ? silenceWindows(dir.direction, ev) : { windows: [], unresolved: [] };
  const doc = deriveCues(score, { silence: win.windows });
  if (win.unresolved.length) doc.issues.push({ severity: "warning", check: "silence-window-unresolved", message: `silence window(s) ${win.unresolved.map((u) => u.id).join(", ")} name an event that is not in the score; they protect nothing until it is fixed` });
  const f = path.join(String(run), "motion", "cues.json");
  fs.mkdirSync(path.dirname(f), { recursive: true });
  const tmp = `${f}.tmp-${process.pid}`;
  fs.writeFileSync(tmp, JSON.stringify(doc, null, 2) + "\n");
  fs.renameSync(tmp, f);
  return { ok: true, cues: doc.cues.length, errors: doc.issues.filter((i) => i.severity === "error").length, warnings: doc.issues.filter((i) => i.severity === "warning").length, score_revision: doc.score_revision, file: "motion/cues.json" };
}
export function cuesFresh(run) {
  const score = rjson(path.join(String(run), "motion", "score.json")), c = rjson(path.join(String(run), "motion", "cues.json"));
  if (!score) return { fresh: false, reason: "no score" };
  if (!c) return { fresh: false, reason: "no cues.json yet" };
  return c.score_revision === scoreRevision(score) ? { fresh: true } : { fresh: false, reason: "cues.json was derived from an older score revision (writeCues regenerates it)" };
}

// the events sound.mjs sfx-plan consumes: id, t (the picture event), kind, plus the cue's intent so sfx-plan can place by it
export function toSfxEvents(resolvedCues) {
  return arr(resolvedCues).filter((c) => c.resolved).map((c) => ({
    id: c.event_id, cue: c.id, t: c.timing.picture_onset_s, kind: c.source.sample || c.role, offset_s: c.intended_offset_s,
    synchronous: c.synchronous || undefined, breaks_silence: c.breaks_silence ? true : undefined,
    ...(c.layers ? { layers: c.layers, purpose: c.purpose, family: c.family, intensity: c.intensity, perceptual_event_id: c.perceptual_event_id } : {}),
  }));
}
